contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        bool reverted1;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        bool reverted2;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assert(
            reverted1 == (feeRate > 5000) &&
            (!reverted1 ? (
                c.initialized() &&
                c.baseToken() == baseToken &&
                c.nft() == nft &&
                c.virtualBaseTokenReserves() == vBase &&
                c.virtualNftReserves() == vNft &&
                c.changeFee() == changeFee &&
                c.feeRate() == feeRate &&
                c.merkleRoot() == merkleRoot &&
                c.useStolenNftOracle() == useOracle &&
                c.payRoyalties() == payRoy &&
                reverted2
            ) : !c.initialized())
        );
    }
}

contract InvMutTest {
