contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address baseToken, address nft, uint128 vb, uint128 vn, uint56 changeFee, uint16 feeRate) public {
        require(feeRate <= 5000);
        require(vn > 1e18);
        c.initialize(baseToken, nft, vb, vn, changeFee, feeRate, bytes32(0), false, false);
        uint16 pfr = Factory(address(c.factory())).protocolFeeRate();
        uint256[] memory ids = new uint256[](1);
        uint256[] memory weights = new uint256[](1);
        ids[0] = 1;
        weights[0] = 1e18;
        bytes32[] memory proofEls = new bytes32[](0);
        bool[] memory flagEls = new bool[](0);
        (uint256 netInput, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(ids, weights, C.MerkleMultiProof({proof: proofEls, flags: flagEls}));
        uint256 gross = netInput - feeAmount - protocolFeeAmount;
        assert(
            netInput == gross + feeAmount + protocolFeeAmount &&
            feeAmount == gross * uint256(feeRate) / 10000 &&
            protocolFeeAmount == gross * uint256(pfr) / 10000
        );
    }
    receive() external payable {}
}

